    {
      "title": "风雨归途与试音准备",
      "location": "老街广播站检修台",
      "dramatic_goal": "展现外部天线修复后的疲惫与急迫，确立带负载试音的安全原则。",
      "lines": [
        {
          "kind": "sfx",
          "text": "狂风呼啸，窗外天线金属碰撞的哐当声",
          "audio_cue_ref": "sfx_wind_and_metal_clash"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "拉紧绝缘绳！别松手！风太大，注意脚下防滑！",
          "audio_cue_ref": "sfx_wind_howl"
        },
        {
          "kind": "sfx",
          "text": "关门声，风雨声被隔绝大半，两人沉重的喘息声",
          "audio_cue_ref": "sfx_door_close_and_panting"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "天线固定死了！终于进来了。林岚，赶紧推闸试音吧，街坊们还等着听暴雨预警呢！"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "先擦干设备。必须进行带负载试音，防止二次短路。把湿透的绝缘手套摘了。",
          "audio_cue_ref": "sfx_wet_gloves_off"
        }
      ]
    },
    {
      "title": "杂音危机与默契清理",
      "location": "调音台前",
      "dramatic_goal": "通过排查音量不稳的故障，展现两人的专业配合与情感拉扯中的克制关心。",
      "lines": [
        {
          "kind": "sfx",
          "text": "推闸声，喇叭传出声音，但伴随严重电流麦，音量忽大忽小",
          "audio_cue_ref": "sfx_switch_and_static_noise"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "怎么全是杂音？声音还忽大忽小的，是不是刚才进水把功放烧毁了？完了完了！"
