        {
          "kind": "sfx",
          "text": "翻找工具声，棉签掉落在地",
          "audio_cue_ref": "sfx_cotton_swab_drop"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "抱歉，手太冷发抖，棉签掉地上了……我重新拿一包。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "拿着杯子。",
          "audio_cue_ref": "sfx_thermos_clink"
